using System;using System.Linq;using System.Text.Json;using MotorwaysSim;
class Check{static TrafficWorld Lab(){var r=Rules.ForVersion(GameVersion.OriginalReference);r.EnableCityGrowth=false;var w=new TrafficWorld(40,false,r);w.Reset(40,ScenarioKind.EmptyLab);return w;}
static void Main(){
var w=Lab();var h=w.SpawnBuilding(new Cell(5,7),0,true,0);var s=w.SpawnBuilding(new Cell(12,5),0,false,0,0);int before=w.Inventory[0];bool drawn=w.DrawRoad(h.Access,s.Access);int after=w.Inventory[0];w.DrawRoad(h.Access,s.Access);Console.WriteLine(JsonSerializer.Serialize(new{fixture="straight house (5,7) to shop access (12,7)",drawn,before,after,afterRedraw=w.Inventory[0],roadCells=Enumerable.Range(6,6).Count(x=>w.Tile(new Cell(x,7))==Infrastructure.Road),originalBaseConnectionCost=5,originalScope="sum of inspected base connection cost: building edges free, five ordinary edges; no challenge modifiers"}));
foreach(int x in Enumerable.Range(6,6))w.Build(BuildTool.Remove,new Cell(x,7));Console.WriteLine(JsonSerializer.Serialize(new{fixture="unused road deletion",roads=w.Inventory[0],pending=w.Observe().PendingRemovals.Sum()}));
w=Lab();w.Inventory[4]=1;w.Build(BuildTool.Road,new Cell(10,10));int pre=w.Inventory[0];bool round=w.Build(BuildTool.Roundabout,new Cell(10,10));w.Build(BuildTool.Remove,new Cell(10,10));Console.WriteLine(JsonSerializer.Serialize(new{fixture="roundabout replaces unused road then removed",round,roadsBeforeConversion=pre,roadsAfterRemoval=w.Inventory[0],roundabouts=w.Inventory[4]}));
w=Lab();w.Step(2800);int stock=w.Inventory[0];int choices=w.UpgradeChoices.Count;w.Step(2800);var offers=w.UpgradeChoices.Select(v=>new{v.Type,v.Amount,v.Roads}).ToArray();int grant=w.UpgradeChoices[0].Roads+(w.UpgradeChoices[0].Type==0?w.UpgradeChoices[0].Amount:0);w.ChooseUpgrade(0);Console.WriteLine(JsonSerializer.Serialize(new{fixture="pending weekly choice",time=w.Time,stockAt140=stock,choicesAt140=choices,choicesAt280=offers,grant,afterChoice=w.Inventory[0]}));
}}
